class Solution {
public:
    int findUnsortedSubarray(vector<int>& nums) {
        int n = nums.size();
        int end = -1, maxSeen = nums[0];
        for (int i = 1; i < n; i++) {
            if (nums[i] < maxSeen) end = i;
            else maxSeen = nums[i];
        }
        int start = 0, minSeen = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] > minSeen) start = i;
            else minSeen = nums[i];
        }
        return end != -1 ? end - start + 1 : 0;
    }
};

